import type Device from '../lib/Device';
import type { ArgumentAutocompleteResults, FlowCardType } from '../lib/FlowCard';
import type { FlowTokenType } from '../lib/FlowToken';
import type Image from '../lib/Image';
export type OnFlowCardRunEvent = {
    args: {
        id: string;
        type: FlowCardType;
        args: Record<string, unknown>;
        state: Record<string, unknown>;
        tokens?: Record<string, unknown>;
        $origin?: Record<string, unknown>;
    };
    return: unknown;
};
export type OnFlowCardUpdateEvent = {
    args: {
        id: string;
        type: FlowCardType;
    };
    return: void;
};
export type OnFlowCardAutocompleteEvent = {
    args: {
        id: string;
        type: FlowCardType;
        name: string;
        query: string;
        args: Record<string, unknown>;
    };
    return: Array<ArgumentAutocompleteResults>;
};
export type OnFlowTokenGetValueEvent = {
    args: {
        id: string;
    };
    return: string | number | boolean | Image | null;
};
export type SetTokenValueEvent = {
    args: {
        tokenId: string;
        tokenValue: unknown;
    };
    return: void;
};
export type RegisterTokenEvent = {
    args: {
        tokenId: string;
        tokenObj: {
            type: FlowTokenType;
            title: string;
            value?: number | string | boolean | Image | null;
        };
    };
    return: void;
};
export type UnregisterTokenEvent = {
    args: {
        tokenId: string;
    };
    return: void;
};
export type TriggerEvent = {
    args: {
        id: string;
        tokens: Record<string, unknown>;
        state: Record<string, unknown>;
    };
    return: void;
};
export type TriggerDeviceEvent = {
    args: {
        id: string;
        device: Device;
        tokens: Record<string, unknown>;
        state: Record<string, unknown>;
    };
    return: void;
};
export type GetFlowCardArgsEvent = {
    args: {
        cardId: string;
        cardType: FlowCardType;
        device?: Device;
    };
    return: Array<Record<string, unknown>>;
};
export type HomeyFlowEvents = {
    onFlowCardRun: OnFlowCardRunEvent;
    onFlowCardUpdate: OnFlowCardUpdateEvent;
    onFlowCardAutocomplete: OnFlowCardAutocompleteEvent;
    onFlowTokenGetValue: OnFlowTokenGetValueEvent;
};
export type SDKFlowEvents = {
    setTokenValue: SetTokenValueEvent;
    registerToken: RegisterTokenEvent;
    unregisterToken: UnregisterTokenEvent;
    trigger: TriggerEvent;
    triggerDevice: TriggerDeviceEvent;
    getFlowCardArgs: GetFlowCardArgsEvent;
};
type BoundClient<TOmit extends string> = {
    emit: <T extends keyof SDKFlowEvents>(event: T, data?: Omit<SDKFlowEvents[T]['args'], TOmit>) => Promise<SDKFlowEvents[T]['return']>;
};
export type FlowTokenClient = BoundClient<'tokenId'>;
export {};
